"""Generate a single standalone website with embedded non-sensitive synthetic test scores.
Works locally, GitHub Pages, and Cloudflare Pages without a Python backend.
"""
from pathlib import Path
R=Path(__file__).resolve().parents[1]
import json
D=json.loads((R/'docs/assets/data.json').read_text())
encoded=json.dumps(D,separators=(',',':')).replace('</','<\\/')
page=r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="description" content="CardGrowth AI: a synthetic data portfolio lab for small-business card experimentation, targeting and unit economics."><title>CardGrowth AI | Strategy Lab</title>
<style>
:root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,Arial,sans-serif;background:#081122;color:#edf3ff;--muted:#9aaac4;--card:#121e33;--border:#2b3b53;--accent:#72d6bd;--blue:#90abff}
*{box-sizing:border-box}body{margin:0}a{color:var(--accent)}.wrap{max-width:1160px;margin:auto;padding:28px 22px 70px}.top{display:flex;justify-content:space-between;align-items:center;gap:12px;border-bottom:1px solid var(--border);padding:17px 0}.mark{font-weight:900;letter-spacing:-.5px;font-size:19px}.mark span{color:var(--accent)}.chip{display:inline-flex;gap:6px;border:1px solid #3d665f;color:var(--accent);border-radius:30px;padding:6px 11px;font-size:11px;font-weight:700;letter-spacing:.6px;text-transform:uppercase}.hero{display:grid;grid-template-columns:1.3fr .7fr;gap:30px;align-items:center;padding:44px 0}.eyebrow{color:var(--accent);font-size:12px;letter-spacing:2px;font-weight:800}.hero h1{font-size:clamp(30px,5vw,58px);line-height:1.06;letter-spacing:-2px;margin:12px 0 16px}.hero p{color:var(--muted);font-size:16px;line-height:1.7}.bigbox{border:1px solid var(--border);background:linear-gradient(135deg,#192e45,#15263b);border-radius:22px;padding:25px}.bigbox strong{font-size:38px;color:var(--accent);display:block;margin:10px 0}.bigbox small{line-height:1.5;color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.kpi,.panel{background:var(--card);border:1px solid var(--border);border-radius:17px;padding:20px}.kpi label{display:block;font-size:12px;color:var(--muted);margin-bottom:10px}.kpi b{font-size:27px;letter-spacing:-1px}.panel{margin-top:20px}.sectionhead{display:flex;justify-content:space-between;align-items:center;gap:10px}.sectionhead h2{margin:2px 0 14px;font-size:22px}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:20px}.controls{display:grid;grid-template-columns:1fr 1fr;gap:20px}.controls label{display:flex;justify-content:space-between;gap:10px;color:#c6d4ea;font-size:13px;margin-bottom:9px}.controls label strong{color:var(--accent)}input[type=range]{width:100%;accent-color:var(--accent)}.field{padding:8px 0}.sub{font-size:12px;color:var(--muted);line-height:1.65}.barrow{margin:15px 0}.barlabel{display:flex;justify-content:space-between;font-size:13px;margin-bottom:8px}.track{width:100%;height:14px;background:#283951;border-radius:10px;overflow:hidden}.fill{height:100%;border-radius:10px;background:var(--accent);width:0;transition:width .2s}.fill.gold{background:#f6bd75}.fill.gray{background:#7995b8}table{width:100%;border-collapse:collapse;font-size:13px}td,th{padding:12px 10px;border-bottom:1px solid #263751;text-align:left}th{color:var(--muted);font-weight:600}.good{color:var(--accent)}.warn{color:#f6bd75}.foot{margin-top:24px;border-top:1px solid var(--border);padding-top:20px;font-size:12px;color:var(--muted);line-height:1.7}.footerlinks{display:flex;flex-wrap:wrap;gap:16px}.warning{background:#282a2d;border:1px solid #6c583c;border-radius:13px;padding:14px;font-size:13px;color:#f1d7ae;margin-top:15px;line-height:1.65}button{background:#273851;color:white;border:1px solid #546b8e;padding:10px 14px;border-radius:8px;cursor:pointer}button:hover{background:#365070}@media(max-width:820px){.hero,.twocol,.controls{grid-template-columns:1fr}.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:420px){.grid{grid-template-columns:1fr}.wrap{padding:18px 12px}.hero h1{letter-spacing:-1px}}
</style></head><body><div class="wrap">
<div class="top"><div class="mark">Card<span>Growth</span> AI <span style="color:#fff;font-size:12px;font-weight:400">/ Strategy Lab</span></div><div class="chip">Synthetic portfolio case</div></div>
<section class="hero"><div><div class="eyebrow">AI × EXPERIMENTATION × PORTFOLIO ECONOMICS</div><h1>Better growth decisions.<br><span style="color:#72d6bd">Not just more applications.</span></h1><p>An interactive small-business card acquisition strategy lab. Compare three experiences, evaluate randomized holdout evidence, and allocate marketing investment with business constraints.</p></div><div class="bigbox"><div class="eyebrow">MODELED HOLDOUT OPPORTUNITY</div><strong id="heroGain">—</strong><small>Predicted incremental first-year contribution across 8,000 synthetic prospects, relative to standard experience. Not observed realized profit.</small></div></section>
<div class="grid"><div class="kpi"><label>Randomized synthetic leads</label><b>48,000</b></div><div class="kpi"><label>Out-of-time holdout</label><b>8,000</b></div><div class="kpi"><label>Chosen predictive model</label><b style="font-size:22px">Logistic</b></div><div class="kpi"><label>Marketing arms</label><b>3</b></div></div>
<section class="panel"><div class="sectionhead"><h2>1 · Experimental evidence</h2><span class="chip">Actual simulated observations</span></div><div class="twocol"><div id="conversionBars"></div><div><table><thead><tr><th>Randomized offer</th><th>Applications</th><th>Rate</th></tr></thead><tbody id="experimentTable"></tbody></table><p class="sub" id="experimentNote"></p></div></div><div class="warning">A statistically detectable increase in applications is not proof of incremental profit. The policy evaluation below uses predictive assumptions, while the randomized off-policy profit estimate remains highly uncertain.</div></section>
<section class="panel"><div class="sectionhead"><h2>2 · Strategy control room</h2><button onclick="resetInputs()">Reset base case</button></div><p class="sub">Adjust offer costs, annual-fee hypothesis, response elasticity, and contact capacity. The dashboard recalculates from 8,000 held-out synthetic model predictions in your browser; no server is required.</p><div class="controls">
<div class="field"><label>Campaign budget <strong id="budgetVal"></strong></label><input id="budget" type="range" min="0" max="6500" step="100" value="2600"></div>
<div class="field"><label>Max targeted prospects <strong id="contactsVal"></strong></label><input id="contacts" type="range" min="0" max="8000" step="100" value="2600"></div>
<div class="field"><label>Cash-flow outreach cost per lead <strong id="cashCostVal"></strong></label><input id="cashCost" type="range" min="0.1" max="2.5" step="0.1" value="0.7"></div>
<div class="field"><label>Rewards outreach cost per lead <strong id="rewardCostVal"></strong></label><input id="rewardCost" type="range" min="0.1" max="3.0" step="0.1" value="1.1"></div>
<div class="field"><label>Cash-flow service cost per activated account <strong id="serviceVal"></strong></label><input id="service" type="range" min="0" max="80" step="2" value="18"></div>
<div class="field"><label>Extra rewards expense (bps of spend) <strong id="rewardBpsVal"></strong></label><input id="rewardBps" type="range" min="0" max="30" step="1" value="12"></div>
<div class="field"><label>Hypothetical uniform annual fee <strong id="feeVal"></strong></label><input id="fee" type="range" min="0" max="120" step="5" value="0"></div>
<div class="field"><label>Demand penalty (pp per $100 fee) <strong id="elasticityVal"></strong></label><input id="elasticity" type="range" min="0" max="4" step="0.25" value="1.2"></div>
</div><div class="grid"><div class="kpi"><label>Predicted incremental contribution</label><b id="gain">—</b></div><div class="kpi"><label>Targeted prospects</label><b id="targeted">—</b></div><div class="kpi"><label>Campaign budget spent</label><b id="spent">—</b></div><div class="kpi"><label>Predicted ROI on contact spend</label><b id="roi">—</b></div></div><p class="sub">This is a model-predicted scenario and greedy budget heuristic, not a causal or production outcome. Uniform annual-fee demand response is an illustrative assumption; product pricing requires separate customer, compliance, and risk validation.</p></section>
<section class="twocol"><div class="panel"><h2>3 · Selected offer mix</h2><div id="mix"></div><p class="sub">A prospect remains on the standard experience if the estimated gain from either alternative is nonpositive or constraints prevent outreach.</p></div><div class="panel"><h2>4 · Targeting by business need</h2><div id="segmentBars"></div><p class="sub">Only simulated operational business attributes are used. These are marketing messages, not individualized APRs or credit decisions.</p></div></section>
<section class="panel"><h2>5 · Evidence audit — why not launch yet?</h2><div class="twocol"><div><p class="sub">Synthetic simulator's known expected improvement for the base-case selected policy:</p><h2 class="good" id="oracle">—</h2><p class="sub">This is a teaching-only oracle available because we generated the data. It is not available in a real bank.</p></div><div><p class="sub">Randomized off-policy financial estimate and 95% confidence interval for base-case selected policy:</p><h2 class="warn" id="ipw">—</h2><p class="sub" id="ipwci"></p></div></div><div class="warning">When the confidence interval includes zero, the correct recommendation is to run a larger, powered experiment with approval, activation, customer-outcome and risk guardrails, not to claim the modeled gain was realized.</div></section>
<div class="foot"><div class="footerlinks"><a href="https://www.fedsmallbusiness.org/2026-report-on-employer-firms" target="_blank" rel="noopener">Federal Reserve 2026 survey</a><a href="https://www.consumerfinance.gov/1071-rule/" target="_blank" rel="noopener">CFPB small-business lending rule</a><a href="https://capitalone.wd12.myworkdayjobs.com/en-US/Capital_One/job/Sr-Business-Analyst---Business-Cards---Payments_R245733" target="_blank" rel="noopener">Capital One role</a></div><p>Methods: chronological train/validation/holdout, 1:1:1 randomized assignment, three-arm T-learner, confidence-aware model selection, first-year economics, budget-limited greedy marketing allocation and Horvitz–Thompson off-policy evaluation. All customer records and financial values are synthetic. Annual fee and rewards cost sliders are hypothetical—not recommendations for lending terms.</p><p>Reproduce the Python analysis using the companion GitHub repository. Designed as an independent portfolio demonstration; not attributable to a real employer.</p></div>
</div><script>const DATA=__DATA__;
const $=id=>document.getElementById(id);
const fmt=(v)=>'$'+Math.round(v).toLocaleString('en-US');
const pct=(v)=>(v*100).toFixed(2)+'%';
const names=['Cash-flow constrained','Growth-focused','Spend-intensive'];
const arms=['Standard','Cash-flow experience','Rewards experience'];
const defaults={budget:2600,contacts:2600,cashCost:.7,rewardCost:1.1,service:18,rewardBps:12,fee:0,elasticity:1.2};
function resetInputs(){for(const [k,v] of Object.entries(defaults))$(k).value=v;compute();}
function putBars(id,arr,maxval){$(id).innerHTML=arr.map((e,i)=>`<div class="barrow"><div class="barlabel"><span>${e[0]}</span><strong>${e[2]}</strong></div><div class="track"><div class="fill ${i==1?'gold':i==2?'gray':''}" style="width:${Math.max(0,e[1]/maxval*100).toFixed(2)}%"></div></div></div>`).join('');}
function experiment(){const obs=DATA.summary.holdout_observed_arms;const a=arms.map(name=>obs.find(x=>x.assigned_offer===name));putBars('conversionBars',a.map(o=>[o.assigned_offer,o.application_rate,pct(o.application_rate)]),.18);$('experimentTable').innerHTML=a.map(o=>`<tr><td>${o.assigned_offer}</td><td>${o.applications}/${o.leads}</td><td>${pct(o.application_rate)}</td></tr>`).join('');$('experimentNote').textContent='Cash-flow lift '+DATA.summary.experiment_significance['Cash-flow experience'].absolute_percentage_point_lift+' pp; reward lift '+DATA.summary.experiment_significance['Rewards experience'].absolute_percentage_point_lift+' pp (unadjusted).';const s=DATA.summary.results.test[DATA.summary.selected];$('oracle').textContent=fmt(s.simulation_oracle.incremental);$('ipw').textContent=fmt(s.off_policy_ipw.estimate);$('ipwci').textContent='95% interval: '+fmt(s.off_policy_ipw.ci95_low)+' to '+fmt(s.off_policy_ipw.ci95_high)+'; includes zero.';}
function compute(){const v={};for(const k of Object.keys(defaults))v[k]=Number($(k).value);
$('budgetVal').textContent=fmt(v.budget);$('contactsVal').textContent=v.contacts.toLocaleString();$('cashCostVal').textContent='$'+v.cashCost.toFixed(2);$('rewardCostVal').textContent='$'+v.rewardCost.toFixed(2);$('serviceVal').textContent=fmt(v.service);$('rewardBpsVal').textContent=v.rewardBps+' bps';$('feeVal').textContent=fmt(v.fee);$('elasticityVal').textContent=v.elasticity.toFixed(2)+' pp';
const rows=DATA.points;const feeShift=(v.fee/100)*(v.elasticity/100);const candidates=[];
for(let i=0;i<rows.length;i++){const r=rows[i];const p=r.p.map(x=>Math.max(0,x-feeShift));const m=[r.m+v.fee,r.m+v.fee-v.service,r.m+v.fee-v.rewardBps/10000*r.v];const raw=[p[0]*r.a*m[0],p[1]*r.a*m[1]-v.cashCost,p[2]*r.a*m[2]-v.rewardCost];const d1=raw[1]-raw[0],d2=raw[2]-raw[0];if(Math.max(d1,d2)>0)candidates.push([Math.max(d1,d2),i,d1>=d2?1:2,r.s]);}
candidates.sort((a,b)=>b[0]-a[0]);let remaining=v.budget,used=0,gain=0;const mix=[0,0,0],counts=[0,0,0];
for(const [g,i,a,s] of candidates){if(used>=v.contacts)break;const cost=a==1?v.cashCost:v.rewardCost;if(cost>remaining+1e-10)continue;remaining-=cost;used++;gain+=g;mix[a]++;counts[s]++;}
mix[0]=rows.length-used;
$('heroGain').textContent=fmt(gain);$('gain').textContent=fmt(gain);$('targeted').textContent=used.toLocaleString();$('spent').textContent=fmt(v.budget-remaining);$('roi').textContent=(v.budget-remaining)>0?(gain/(v.budget-remaining)*100).toFixed(0)+'%':'n/a';
putBars('mix',arms.map((a,i)=>[a,mix[i],mix[i].toLocaleString()]),rows.length);
putBars('segmentBars',names.map((a,i)=>[a,counts[i],counts[i].toLocaleString()+' treated']),Math.max(1,...counts));}
for(const k of Object.keys(defaults))$(k).addEventListener('input',compute);
experiment();compute();</script></body></html>'''
(R/'docs/index.html').write_text(page.replace('__DATA__',encoded),encoding='utf-8')
(R.parent/'CardGrowth_AI_Decision_Lab.html').write_text(page.replace('__DATA__',encoded),encoding='utf-8')
print('wrote',R/'docs/index.html',(R/'docs/index.html').stat().st_size,'bytes')
